import styles from "./event-row.module.less";
import Link from "@/core/components/primitives/link/link";
import { Event } from "@/core/components/primitives/calendar/types/calendar-types";
import { ShowNode } from "@/core/stores/show-store";
import { DateHelper, PlaceholderImageHelper } from "@/core/helpers";
import { GatsbyImage } from "gatsby-plugin-image";
import { buttonLinkIsInternal } from "@/core/components/primitives/parks-button/parks-button";
import { useOpeningHoursForDate } from "@/core/hooks";
import { useTranslation } from "react-i18next";
import Icon from "@/core/components/primitives/icon/icon";
import { multipleClassNames } from "@/core/helpers/string-helper";
import { SpokenText } from "@/core/components/primitives/spoken-text/spoken-text";

export type EventRowProps = {
  event: Event;
  show?: ShowNode;
  hideLinkIcon?: boolean;
  onClick?: string | (() => void);
  isEventDisplay?: boolean;
};

const EventRowContent = ({ event, show, hideLinkIcon, isEventDisplay }: EventRowProps) => {
  const { t } = useTranslation();
  const openingHours = useOpeningHoursForDate(event.startDateAndTime);
  const dateStr = isEventDisplay ? DateHelper.toStringDDMonth(event.startDateAndTime) : "";

  let time = `${DateHelper.toStringTimeHHMM(event.startDateAndTime)}${
    event.endDateAndTime ? " - " + DateHelper.toStringTimeHHMM(event.endDateAndTime) : ""
  }`;

  if (show?.openEntireDay && openingHours) {
    time = `${DateHelper.toStringTimeHHMM(openingHours.opens)} - ${DateHelper.toStringTimeHHMM(openingHours.closing)}`;
  }

  const gatsbyImageData = show?.imageInList?.gatsbyImageData;
  const fileUrl = show?.imageInList?.file?.url;
  const fallbackImage = PlaceholderImageHelper.getPlaceholderImage("eventRow");

  return (
    <>
      {event.cancelled && <SpokenText text={t("eventRowCancelledSpokenText")} />}
      {gatsbyImageData ? (
        <GatsbyImage className={styles.image} image={gatsbyImageData} alt={event.title} />
      ) : fileUrl ? (
        <img className={styles.image} src={fileUrl} alt={event.title} />
      ) : (
        <img className={styles.image} src={fallbackImage} alt={event.title} />
      )}
      <div className={multipleClassNames(styles.inner, event.cancelled && styles.cancelled)}>
        <h4 className={styles.time}>
          {dateStr && `${dateStr} `}
          {time}
        </h4>
        <ul className={styles.metaRows}>
          {event.title && (
            <li>
              <Icon name="theater" className={styles.metaRowIcon} />
              <span>{event.title}</span>
            </li>
          )}
          {show?.location && (
            <li>
              <Icon name="location" className={styles.metaRowIcon} />
              <span>{show.location}</span>
            </li>
          )}
        </ul>
        {!hideLinkIcon && <Icon name="chevron-right" className={styles.rightIcon} />}
      </div>
      {event.cancelled && <CancelledLabel />}
    </>
  );
};

const CancelledLabel = () => {
  const { t } = useTranslation();
  return (
    <p data-contentful-label-id="eventRowCancelledLabelText" className={styles.cancelledLabel}>
      {t("eventRowCancelledLabelText")}
    </p>
  );
};

const EventRow = ({ onClick, ...props }: EventRowProps) => {
  const rowClass = multipleClassNames(
    styles.row,
    !onClick && styles.noLink,
    props.isEventDisplay && styles.isEventDisplay,
  );

  if (typeof onClick === "string") {
    return (
      <Link
        internalLink={buttonLinkIsInternal(onClick) ? onClick : undefined}
        externalLink={buttonLinkIsInternal(onClick) ? undefined : onClick}
        className={rowClass}
        title={props.event.description}
      >
        <EventRowContent {...props} />
      </Link>
    );
  }

  if (typeof onClick === "function") {
    return (
      <div role="button" onClick={onClick} className={rowClass}>
        <EventRowContent {...props} />
      </div>
    );
  }

  return (
    <div className={rowClass}>
      <EventRowContent {...props} hideLinkIcon />
    </div>
  );
};

export default EventRow;
